PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_Level : INT := 0;
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    low_limit : INT := 10;
    high_limit : INT := 90;
    safety_timer : TON;
END_VAR

// Check for safety condition: PumpIn must not run if Level >= high_limit
IF NOT prev_PumpIn AND PumpIn THEN
    safety_timer(IN := TRUE, PT := T#1s);
END_IF;

// Implement hysteresis logic for PumpIn and ValveOut
IF Level <= low_limit THEN
    PumpIn := TRUE;
ELSIF Level >= high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := prev_PumpIn;
    ValveOut := FALSE;
END_IF;

// Update previous values for next cycle
prev_Level := Level;
prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;

// Reset safety timer if condition is cleared
IF NOT safety_timer.Q THEN
    safety_timer(IN := FALSE);
END_IF;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    LastLevel : INT := 0;
END_VAR

// Check if the level has changed significantly to avoid oscillation
IF ABS(Level - LastLevel) >= 5 THEN
    LastLevel := Level;

    // Turn on the pump if the level is below the low limit and not above the high limit
    IF Level <= LowLimit AND Level < HighLimit THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSIF Level >= HighLimit THEN
        // Turn off the pump and open the valve if the level is at or above the high limit
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        // Keep the pump off and close the valve otherwise
        PumpIn := FALSE;
        ValveOut := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM tank_level
