    hysteresis_threshold : INT := 5;
END_VAR

// Check if the level has changed significantly to avoid oscillation
IF ABS(Level - prev_Level) >= hysteresis_threshold THEN
    prev_Level := Level;

    // Turn on the pump if the level is below the low limit and not above the high limit
    IF Level <= 10 AND NOT (Level >= 90) THEN
        PumpIn := TRUE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    // Always open the outlet valve if the level is at or above the high limit
    IF Level >= 90 THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;

    // Ensure the pump does not run when the level is at or above the high limit
    IF Level >= 90 THEN
        PumpIn := FALSE;
    END_IF;

    prev_PumpIn := PumpIn;
    prev_ValveOut := ValveOut;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
