VAR
    prev_Level : INT := 0;
    hysteresis_high : INT := 85;
    hysteresis_low : INT := 15;
    pump_timer : TON;
END_VAR

// Check for overflow condition
IF Level >= hysteresis_high THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= hysteresis_low THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Implement hysteresis logic
IF Level < prev_Level AND Level > hysteresis_low THEN
    PumpIn := TRUE;
ELSIF Level > prev_Level AND Level < hysteresis_high THEN
    PumpIn := FALSE;
END_IF;

prev_Level := Level;
END_PROGRAM

