PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpTimer : TON;
    LastLevel : INT := 0;
END_VAR

// Check if the level has changed significantly enough to trigger an action
IF ABS(Level - LastLevel) >= 5 THEN
    // Update the last recorded level
    LastLevel := Level;

    // Turn on the pump if the level is below the low limit and not at or above the high limit
    IF Level <= 10 AND Level < 90 THEN
        PumpIn := TRUE;
        PumpTimer(IN := TRUE, PT := T#0s);
    ELSIF Level >= 90 THEN
        // Turn off the pump and open the valve if the level is at or above the high limit
        PumpIn := FALSE;
        ValveOut := TRUE;
        PumpTimer(IN := FALSE, PT := T#0s);
    ELSE
        // Otherwise, keep the pump running and close the valve
        PumpIn := TRUE;
        ValveOut := FALSE;
        PumpTimer(IN := TRUE, PT := T#0s);
    END_IF;
END_IF;

// Reset the pump after a short delay to avoid oscillation
IF PumpTimer.Q THEN
    PumpIn := FALSE;
    ValveOut := FALSE;
    PumpTimer(IN := FALSE, PT := T#0s);
END_IF;
END_PROGRAM

