PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TGreen_NS, TYellow_NS, TAllRed_NS, TGreen_EW, TYellow_EW, TAllRed_EW : TON;
END_VAR

TGreen_NS(IN := State = 0 OR State = 3, PT := T#2s);
TYellow_NS(IN := State = 1 OR State = 4, PT := T#1s);
TAllRed_NS(IN := State = 2 OR State = 5, PT := T#1s);

TGreen_EW(IN := State = 3 OR State = 0, PT := T#2s);
TYellow_EW(IN := State = 4 OR State = 1, PT := T#1s);
TAllRed_EW(IN := State = 5 OR State = 2, PT := T#1s);

NS_G := TGreen_NS.Q AND NOT TYellow_NS.Q AND NOT TAllRed_NS.Q;
NS_Y := TYellow_NS.Q AND NOT TGreen_NS.Q AND NOT TAllRed_NS.Q;
NS_R := TAllRed_NS.Q OR (NOT TGreen_NS.Q AND NOT TYellow_NS.Q);

EW_G := TGreen_EW.Q AND NOT TYellow_EW.Q AND NOT TAllRed_EW.Q;
EW_Y := TYellow_EW.Q AND NOT TGreen_EW.Q AND NOT TAllRed_EW.Q;
EW_R := TAllRed_EW.Q OR (NOT TGreen_EW.Q AND NOT TYellow_EW.Q);

CASE State OF
    0: State := 1;
    1: State := 2;
    2: State := 3;
    3: State := 4;
    4: State := 5;
    5: State := 0;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
    State : INT := 0;
    green_timer : TON;
    yellow_timer : TON;
    all_red_timer : TON;
END_VAR

green_timer(IN := State = 0 OR State = 3, PT := T#2s);
yellow_timer(IN := State = 1 OR State = 4, PT := T#1s);
all_red_timer(IN := State = 2 OR State = 5, PT := T#1s);

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := TRUE;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := TRUE;
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
END_CASE;

State := State + 1;
IF State > 5 THEN
    State := 0;
END_IF;

NS_G := NS_G AND NOT green_timer.Q;
NS_Y := NS_Y AND NOT yellow_timer.Q;
NS_R := NS_R AND NOT all_red_timer.Q;
EW_G := EW_G AND NOT green_timer.Q;
EW_Y := EW_Y AND NOT yellow_timer.Q;
EW_R := EW_R AND NOT all_red_timer.Q;
END_PROGRAM

PROGRAM intersection
VAR
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
    State : INT := 0;
    NS_green : TON;
    NS_yellow : TON;
    NS_allred : TON;
    EW_green : TON;
    EW_yellow : TON;
    EW_allred : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

NS_green(IN := State = 0 OR State = 3, PT := PT_GREEN);
NS_yellow(IN := State = 1 OR State = 4, PT := PT_YELLOW);
NS_allred(IN := State = 2 OR State = 5, PT := PT_ALLRED);

EW_green(IN := State = 3 OR State = 0, PT := PT_GREEN);
EW_yellow(IN := State = 4 OR State = 1, PT := PT_YELLOW);
EW_allred(IN := State = 5 OR State = 2, PT := PT_ALLRED);

NS_G := NS_green.Q AND NOT NS_yellow.Q AND NOT NS_allred.Q;
NS_Y := NS_yellow.Q AND NOT NS_green.Q AND NOT NS_allred.Q;
NS_R := NS_allred.Q OR (NS_green.Q AND NS_yellow.Q);

EW_G := EW_green.Q AND NOT EW_yellow.Q AND NOT EW_allred.Q;
EW_Y := EW_yellow.Q AND NOT EW_green.Q AND NOT EW_allred.Q;
EW_R := EW_allred.Q OR (EW_green.Q AND EW_yellow.Q);

CASE State OF
    0: State := 1;
    1: State := 2;
    2: State := 3;
    3: State := 4;
    4: State := 5;
    5: State := 0;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
    State : INT := 0;
    T_Green_NS : TON;
    T_Yellow_NS : TON;
    T_AllRed : TON;
END_VAR

T_Green_NS(IN := State = 0 OR State = 3, PT := T#2s);
T_Yellow_NS(IN := State = 1 OR State = 4, PT := T#1s);
T_AllRed(IN := State = 2 OR State = 5, PT := T#1s);

NS_G := NOT T_Green_NS.Q AND NOT T_Yellow_NS.Q AND NOT T_AllRed.Q;
NS_Y := T_Yellow_NS.Q;
NS_R := T_AllRed.Q;

EW_G := NOT T_Green_NS.Q AND NOT T_Yellow_NS.Q AND NOT T_AllRed.Q;
EW_Y := T_Yellow_NS.Q;
EW_R := T_AllRed.Q;

CASE State OF
    0:
        // NS green, EW red
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        // NS yellow, EW red
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        // All red clearance
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        // EW green, NS red
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
    4:
        // EW yellow, NS red
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
    5:
        // All red clearance
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
END_CASE;

// Update state machine
IF T_Green_NS.Q THEN
    State := State + 1;
ELSIF T_Yellow_NS.Q THEN
    State := State + 1;
ELSIF T_AllRed.Q THEN
    State := State + 1;
END_IF;

IF State > 5 THEN
    State := 0;
END_IF;
END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL := FALSE;
    TNS_G, TNS_Y, TNS_AllRed, TEW_G, TEW_Y, TEW_AllRed : TON;
END_VAR

TNS_G(IN := State = 0 OR State = 3, PT := T#2s);
