    StartTimer : TON;
    MotorStarted : BOOL := FALSE;
END_VAR

CONSTANT
    PT_DELAY : TIME := T#3s;
END_CONSTANT

IF NOT EStop THEN
    // Emergency stop activated, reset motor state and timer
    MotorStarted := FALSE;
    StartTimer(IN := FALSE);
    Motor := FALSE;
ELSIF StartCmd AND NOT MotorStarted THEN
    // Start command received and motor not yet started
    StartTimer(IN := TRUE, PT := PT_DELAY);
    IF StartTimer.Q THEN
        // Start command held for required time, motor can start
        MotorStarted := TRUE;
        Motor := TRUE;
    END_IF;
ELSIF NOT StartCmd AND MotorStarted THEN
    // Start command released after motor was started
    MotorStarted := FALSE;
    Motor := FALSE;
END_IF;

