IF NOT EStop OR NOT StartCmd THEN
    MotorStarted := FALSE;
    StartTimer(IN := FALSE);
END_IF;

// If EStop is not active and StartCmd is held, start the timer
IF EStop AND StartCmd THEN
    StartTimer(IN := TRUE, PT := T#3s);

    // If the timer reaches its preset time, set Motor to TRUE
    IF StartTimer.Q THEN
        MotorStarted := TRUE;
        Motor := TRUE;
    END_IF;
END_IF;

// Reset Motor if StartCmd is released before the timer expires
IF NOT StartCmd AND MotorStarted THEN
    MotorStarted := FALSE;
    Motor := FALSE;
    StartTimer(IN := FALSE);
END_IF;

