PROGRAM ped_crossing
VAR_INPUT
    PedReq : BOOL;
END_VAR
VAR_OUTPUT
    CarGreen : BOOL;
    CarYellow : BOOL;
    CarRed : BOOL;
    PedWalk : BOOL;
END_VAR
VAR
    State : INT := 0;
    GreenTimer : TON;
    YellowTimer : TON;
    WalkTimer : TON;
    PT_GREEN : TIME := T#3s;
    PT_YELLOW : TIME := T#2s;
    PT_WALK : TIME := T#3s;
END_VAR

CASE State OF
    0: // Cars green, Pedestrian don't walk
        CarGreen := TRUE;
        CarYellow := FALSE;
        CarRed := FALSE;
        PedWalk := FALSE;

        IF PedReq AND NOT GreenTimer.Q THEN
            GreenTimer(IN := TRUE, PT := PT_GREEN);
            State := 1;
        END_IF;

    1: // Cars yellow
        CarGreen := FALSE;
        CarYellow := TRUE;
        CarRed := FALSE;
        PedWalk := FALSE;

        IF GreenTimer.Q AND NOT YellowTimer.Q THEN
            YellowTimer(IN := TRUE, PT := PT_YELLOW);
            State := 2;
        END_IF;

    2: // Cars red, Pedestrian walk
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;

        IF YellowTimer.Q AND NOT WalkTimer.Q THEN
            WalkTimer(IN := TRUE, PT := PT_WALK);
            State := 0;
        END_IF;
END_CASE;

// Reset timers when state changes
IF State <> 0 THEN
    GreenTimer(IN := FALSE);
END_IF;
IF State <> 1 THEN
    YellowTimer(IN := FALSE);
END_IF;
IF State <> 2 THEN
    WalkTimer(IN := FALSE);
END_IF;
