PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

// Detect falling edge of Demand for Lead change
PrevDemand := Demand;

// Check for emergency stop
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0;
    Exit;
END_IF;

// Alternate Lead on falling edge of Demand
IF NOT PrevDemand AND Demand THEN
    Lead := 1 - Lead; // Toggle Lead
END_IF;

// Assign pumps based on Lead state
CASE Lead OF
    0:
        Pump1 := Demand;
        Pump2 := FALSE;
    1:
        Pump1 := FALSE;
        Pump2 := Demand;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
END_CASE;

END_PROGRAM

